import{R as e,e as o,f as a,U as n}from"./chunks/framework.ywem4qy5.js";const p=JSON.parse('{"title":"Avochato","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/crm/avochato.md","filePath":"integrations/crm/avochato.md","lastUpdated":1775908585000}'),i={name:"integrations/crm/avochato.md"};function r(l,t,s,h,c,g){return o(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="avochato" tabindex="-1">Avochato <a class="header-anchor" href="#avochato" aria-label="Permalink to &quot;Avochato&quot;">​</a></h1><p>Follow the below steps to connect to the Avochato API.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>CRM</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select Avochato as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-avochato-api" tabindex="-1">Step 2. Connect to the Avochato API <a class="header-anchor" href="#step-2-connect-to-the-avochato-api" aria-label="Permalink to &quot;Step 2. Connect to the Avochato API&quot;">​</a></h3><ol><li>Go to <a href="https://www.avochato.com/" target="_blank">Avochato</a> and login to your account.</li><li>In the left-hand sidebar menu, click on <strong>Settings</strong>.</li><li>Click the <strong>Generate Credentials</strong> button.</li><li>Copy the <strong>Auth ID</strong> from Avochato and paste in the <strong>Auth ID</strong> field in Formie.</li><li>Copy the <strong>Auth Secret</strong> from Avochato and paste in the <strong>Auth Secret</strong> field in Formie.</li></ol><h3 id="step-3-test-connection" tabindex="-1">Step 3. Test Connection <a class="header-anchor" href="#step-3-test-connection" aria-label="Permalink to &quot;Step 3. Test Connection&quot;">​</a></h3><ol><li>Save this integration.</li><li>Click on the <strong>Refresh</strong> button in the right-hand sidebar.</li></ol><h3 id="step-4-form-setting" tabindex="-1">Step 4. Form Setting <a class="header-anchor" href="#step-4-form-setting" aria-label="Permalink to &quot;Step 4. Form Setting&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Click the <strong>Integrations</strong> tab.</li><li>In the left-hand sidebar, select the name you gave the integration.</li><li>Enable the integration and fill out all required fields.</li><li>Click <strong>Save</strong> to save the form.</li></ol>',10)])])}const m=e(i,[["render",r]]);export{p as __pageData,m as default};
